using UnityEngine;

// One enemy type: animation frames + stats. Assets live in Assets/Enemies/ (Rat, Spider,
// Slime, Mushroom, Bear) and are generated by the editor's EnemyAssets builder from the PNGs that
// generate_enemy_sprites.ps1 draws. All frames of a type share one canvas size with a
// bottom-center pivot, so the transform position is simply where the feet touch the ground.
[CreateAssetMenu(menuName = "Cats Smash/Enemy Definition")]
public class EnemyDefinition : ScriptableObject
{
    public enum CombatRole { Chaser, Ranged, Tank, Ambusher }

    public string displayName;
    public bool isBoss;
    [Tooltip("Chaser: quick melee. Ranged: web shot. Tank: extra HP. Ambusher: short burst and lunge.")]
    public CombatRole combatRole;

    [Header("Animation")]
    public Sprite[] idleFrames;
    public Sprite[] moveFrames;
    public Sprite[] attackFrames;
    public Sprite[] hurtFrames;
    public Sprite[] deathFrames;
    public float idleFps = 4f;
    public float moveFps = 8f;
    public float attackFps = 8f;
    public float deathFps = 5f;
    [Tooltip("How far (in sprite pixels) a planted foot slides back per walk frame. Set = the walk is driven by the distance actually covered, so the feet keep pace with any speed (a boss's faster phases, its charge); 0 = plays at moveFps.")]
    public float walkStridePixels = 0f;
    [Tooltip("Attack frame on which the bite/stab/claw actually lands.")]
    public int attackHitFrame = 1;

    [Header("Stats")]
    public int hp = 2;
    public int goldReward = 5;
    [Tooltip("Hearts taken from the player per hit.")]
    public float damage = 0.5f;
    public float moveSpeed = 2f;
    [Tooltip("World scale of the sprite (sprites are 16 px per unit).")]
    public float scale = 1.5f;
    [Tooltip("Body-size radius used by the player's attacks to reach this enemy.")]
    public float hitRadius = 1.2f;
    [Tooltip("Half width of the body for walking into walls / off ledges.")]
    public float bodyHalfWidth = 0.6f;

    [Header("Behaviour")]
    [Tooltip("Starts chasing when the player is this close horizontally (and roughly on the same level).")]
    public float aggroRange = 8f;
    [Tooltip("Starts an attack when the player is this close horizontally.")]
    public float attackRange = 1.6f;
    public float attackCooldown = 1.2f;
    public float knockback = 0.8f;
    [Tooltip("Wanders this far left/right of its spawn point while it hasn't seen the player.")]
    public float patrolRange = 3f;
    [Tooltip("Lunges this far forward during the attack wind-up (0 = attacks in place).")]
    public float lungeDistance;
    [Tooltip("After spotting the player, keeps chasing this long even if the player jumps out of its level.")]
    public float alertTime = 2.5f;
    [Tooltip("Ignores hit-stun (bosses keep attacking when hit).")]
    public bool superArmor;
    [Tooltip("Attacks from range: on the hit frame it spits EnemyWeb at the player instead of biting (attackRange = how far it shoots from).")]
    public bool ranged;
    [Tooltip("Ranged: keeps at least this far from the player, backing off while its attack recharges.")]
    public float keepAway = 0f;

    [Header("Sound (Sfx ids)")]
    [Tooltip("Played on the attack's hit frame (empty = silent).")]
    public string attackSound = "";
    public string deathSound = "enemy_death";

    [Header("Effects (Vfx ids, '|' plays several)")]
    [Tooltip("Played where it dies: a pale smoke puff for the little ones, a green splash for the slime, a big explosion for the boss.")]
    public string deathEffect = "smoke_big";
    public float deathEffectScale = 1f;
    [Tooltip("Played on the attack's hit frame in front of it (empty = none), e.g. the slime's green splat.")]
    public string attackEffect = "";
    public float attackEffectScale = 1f;

    [Header("Boss")]
    [Tooltip("What falls from the ceiling when the boss pounds the floor (the bear's rocks; empty = no rock fall).")]
    public Sprite fallingRock;
    [Tooltip("Second line of the boss's entrance banner.")]
    public string bossTitle = "";
}
